record.field:
{
    "type": "object",
    "properties": {
        "title": {"type": "string", "maxLength": 120, "description": "Short name of the need, e.g. 'Laptops for 25 new hires'."},
        "need_summary": {"type": "string", "maxLength": 2000, "description": "What is bought, for whom, for which use and context, in a few sentences."},
        "product_category": {"type": "string", "maxLength": 120, "description": "Product category name, e.g. 'IT hardware', 'Furniture', 'Workwear'."},
        "budget": {"type": "number", "minimum": 0, "description": "Total budget in the company currency, taxes included."},
        "deadline": {"type": "string", "maxLength": 10, "pattern": "^\\d{4}-\\d{2}-\\d{2}$", "description": "Date by which everything must be delivered, YYYY-MM-DD."},
        "delivery_location": {"type": "string", "maxLength": 250, "description": "Where to deliver (site, address, floor, access constraints)."}
    },
    "required": []
}

{
    "type": "object",
    "properties": {
        "items": {
            "type": "array",
            "description": "Every item to buy.",
            "items": {
                "type": "object",
                "properties": {
                    "name": {"type": "string", "maxLength": 120, "description": "Item name, e.g. '14-inch business laptop'."},
                    "quantity": {"type": "number", "minimum": 0, "description": "Quantity to buy."},
                    "unit": {"type": "string", "maxLength": 30, "description": "Unit of measure, e.g. 'Units', 'm', 'kg', 'Hours'. Defaults to Units."},
                    "target_unit_price": {"type": "number", "minimum": 0, "description": "Realistic market unit price in the company currency, used for the budget check only."},
                    "description": {"type": "string", "maxLength": 1000, "description": "One or two sentences on the intended use."},
                    "attributes": {
                        "type": "array",
                        "description": "Specification of the item.",
                        "items": {
                            "type": "object",
                            "properties": {
                                "name": {"type": "string", "maxLength": 80, "description": "Characteristic, e.g. 'RAM', 'Fabric', 'Seat height'."},
                                "value": {"type": "string", "maxLength": 250, "description": "Required value, e.g. '16', 'Cotton 200 g/m2', 'min. 45'."},
                                "unit": {"type": "string", "maxLength": 30, "description": "Unit of the value, e.g. 'GB', 'cm'."},
                                "mandatory": {"type": "boolean", "description": "False for nice-to-have characteristics."}
                            },
                            "required": ["name", "value"]
                        }
                    }
                },
                "required": ["name", "quantity", "attributes"]
            }
        }
    },
    "required": ["items"]
}

{
    "type": "object",
    "properties": {
        "requirements": {
            "type": "array",
            "description": "Every general requirement.",
            "items": {
                "type": "object",
                "properties": {
                    "name": {"type": "string", "maxLength": 120, "description": "e.g. 'Installation and assembly on site'."},
                    "description": {"type": "string", "maxLength": 1000, "description": "Details the vendor needs."},
                    "mandatory": {"type": "boolean", "description": "False for nice-to-have requirements."}
                },
                "required": ["name"]
            }
        }
    },
    "required": ["requirements"]
}
